<?php

declare(strict_types=1);

if (basename((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === basename(__FILE__)) { http_response_code(403); exit; }

function project_workspace_url(string $projectId,string $section='overview',array $extra=[]): string
{
    return module_url('project_workspace',array_replace(['project'=>$projectId,'section'=>$section],$extra));
}

function project_workspace_available_projects(string $classId,string $studentKey): array
{
    $out=[];foreach((array)(project_catalog()[$classId]??[]) as $p){if(!is_array($p)||(string)($p['type']??'')!=='group')continue;$g=project_group_for_student($classId,(string)$p['id'],$studentKey);if($g)$out[]=['project'=>$p,'group'=>$g];}return $out;
}

function project_workspace_role_badge(array $role): string
{
    $def=project_role_definition((string)$role['role']);return '<span class="pw-role-chip '.e((string)$role['role']).'"><i>'.e((string)($def['icon']??'•')).'</i>'.e((string)($def['name']??$role['role'])).'<small>'.e((string)($role['role_type']??'secondary')==='primary'?tr('primární'):'support').'</small></span>';
}


function render_project_workspace_view(string $classId,array $module,string $flash=''): void
{
    $me=social_current_student_key($classId);$students=project_students_for_class($classId);$available=project_workspace_available_projects($classId,$me);$projectId=is_string($_GET['project']??null)?(string)$_GET['project']:'';
    $selected=null;foreach($available as $row)if((string)$row['project']['id']===$projectId){$selected=$row;break;}if(!$selected)$selected=$available[0]??null;
    render_header('Project Workspace',$module);
    if($flash!=='')echo '<div class="notice">'.e($flash).'</div>';
    if(!$selected){?>
      <section class="hero pw-empty-hero"><div class="eyebrow">Project Workspace</div><h1><?=e(tr('Nejdřív potřebuješ projektový tým.'))?></h1><p><?=e(tr('Jakmile se studentské lobby uzamkne, vytvoří se společný workspace pro role, práci, QA a retrospektivu.'))?></p><div class="hero-actions"><a class="btn primary" href="?view=project_lobbies"><?=e(tr('Otevřít Team Finder'))?></a></div></section>
    <?php render_footer();return;}
    $project=$selected['project'];$group=$selected['group'];$projectId=(string)$project['id'];$groupId=(string)$group['id'];$section=is_string($_GET['section']??null)?(string)$_GET['section']:'overview';if(!in_array($section,['overview','work','team','qa','reflect'],true))$section='overview';
    $roles=project_roles_for_student($groupId,$me);$allRoles=project_roles_for_group($groupId);$health=project_workspace_health($classId,$projectId,$groupId);$summary=project_workspace_student_summary($classId,$projectId,$groupId,$me);$coverage=$health['coverage'];$tasks=project_tasks_for_group($groupId);$qa=project_qa_for_group($groupId);$pulse=$health['pulse'];$next=$summary['next_action'];$retroStatus=project_retro_status($groupId);
    $hasPrimary=false;foreach($roles as $r)if((string)($r['role_type']??'')==='primary'){$hasPrimary=true;break;}$missingRequired=count(array_filter($coverage,static fn($c):bool=>(string)($c['requirement']??'')==='required'&&empty($c['covered'])));
    $stage=$retroStatus==='open'?'reflect':((!$hasPrimary||$missingRequired>0)?'roles':($health['qa_open']>0?'qa':($health['completion']>=70?'qa':($tasks?'build':'plan'))));
    $stages=['team'=>tr('Tým'),'roles'=>tr('Role'),'plan'=>tr('Plán'),'build'=>tr('Realizace'),'qa'=>tr('Kontrola'),'reflect'=>tr('Reflexe')];$stageOrder=['team'=>0,'roles'=>1,'plan'=>2,'build'=>3,'qa'=>4,'reflect'=>5];$currentIdx=$stageOrder[$stage]??3;
    ?>
    <section class="pw-project-head">
      <div><div class="eyebrow">Project Workspace · <?=e((string)$group['name'])?></div><h1><?=e((string)$project['title'])?></h1><p><?=e((string)$project['summary'])?></p></div>
      <div class="pw-head-progress"><strong><?= (int)$health['completion'] ?> %</strong><span><?=e(tr('{done} / {total} úkolů hotovo',['done'=>(int)$health['tasks_done'],'total'=>(int)$health['tasks_total']]))?></span></div>
    </section>
    <?php if(count($available)>1):?><nav class="pw-project-switcher"><?php foreach($available as $row):?><a class="<?=((string)$row['project']['id']===$projectId)?'active':''?>" href="<?=e(project_workspace_url((string)$row['project']['id'],$section))?>"><small><?=e((string)$row['group']['name'])?></small><strong><?=e((string)$row['project']['title'])?></strong></a><?php endforeach;?></nav><?php endif;?>
    <div class="pw-lifecycle" aria-label="<?=e(tr('Fáze projektu'))?>"><?php foreach($stages as $key=>$label):$idx=$stageOrder[$key];?><span class="<?=$idx<$currentIdx?'done':($idx===$currentIdx?'active':'')?>"><i><?=$idx<$currentIdx?'✓':($idx+1)?></i><?=e($label)?></span><?php endforeach;?></div>
    <nav class="pw-tabs" aria-label="Project Workspace"><a class="<?=$section==='overview'?'active':''?>" href="<?=e(project_workspace_url($projectId,'overview'))?>"><?=e(tr('Přehled'))?></a><a class="<?=$section==='work'?'active':''?>" href="<?=e(project_workspace_url($projectId,'work'))?>"><?=e(tr('Moje práce'))?></a><a class="<?=$section==='team'?'active':''?>" href="<?=e(project_workspace_url($projectId,'team'))?>"><?=e(tr('Tým'))?></a><a class="<?=$section==='qa'?'active':''?>" href="<?=e(project_workspace_url($projectId,'qa'))?>">QA<?php if($health['qa_open']):?><b><?= (int)$health['qa_open'] ?></b><?php endif;?></a><a class="<?=$section==='reflect'?'active':''?>" href="<?=e(project_workspace_url($projectId,'reflect'))?>"><?=e(tr('Reflexe'))?></a></nav>

    <?php if(!$hasPrimary):?>
      <section class="pw-role-onboarding"><div><span class="eyebrow"><?=e(tr('Nejdřív si ujasni odpovědnost'))?></span><h2><?=e(tr('Vyber svou primární projektovou roli'))?></h2><p><?=e(tr('Role není hodnost ani zákaz dělat jiné věci. Říká pouze, za kterou oblast budeš v týmu primárně ručit.'))?></p></div><a class="btn primary" href="<?=e(project_workspace_url($projectId,'team',['pick_role'=>1]))?>"><?=e(tr('Vybrat roli'))?></a></section>
    <?php endif;?>

    <?php if($section==='overview'): ?>
      <div class="pw-overview-grid">
        <section class="pw-next-action">
          <div class="eyebrow"><?=e(tr('Moje další akce'))?></div>
          <?php if($next):?><span class="pw-task-state status-<?=e((string)$next['status'])?>"><?=e(project_workspace_task_status_label((string)$next['status']))?></span><h2><?=e((string)$next['title'])?></h2><p><?=e((string)($next['description']!==''?$next['description']:tr('Tento úkol je teď nejlogičtější další krok.')))?></p><div class="pw-next-meta"><?php if(!empty($next['role'])):?><span><?=e(project_role_label((string)$next['role']))?></span><?php endif;?><?php if(!empty($next['due_at'])):?><span><?=e(tr('Termín {date}',['date'=>date('d.m.',strtotime((string)$next['due_at']))]))?></span><?php endif;?><span><?=e(tr('Komplexita {n}/5',['n'=>(int)$next['complexity']]))?></span></div><a class="btn primary" href="<?=e(project_workspace_url($projectId,'work',['task'=>(string)$next['id']]))?>"><?=e(tr('Pokračovat →'))?></a>
          <?php else:?><div class="pw-all-clear"><i>✓</i><h2><?=e(tr('Nemáš otevřený vlastní úkol.'))?></h2><p><?=e(tr('Zkontroluj týmový board nebo pomoz spolužákovi, který čeká na podporu.'))?></p><a class="btn secondary" href="<?=e(project_workspace_url($projectId,'work'))?>"><?=e(tr('Otevřít práci týmu'))?></a></div><?php endif;?>
        </section>
        <section class="dashboard-panel pw-my-role"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Moje odpovědnost'))?></div><h2><?= $roles?e(project_role_label((string)($roles[0]['role']??''))):e(tr('Role zatím není vybraná')) ?></h2></div><a class="text-link" href="<?=e(project_workspace_url($projectId,'team'))?>"><?=e(tr('Role →'))?></a></div><?php if($roles):?><div class="pw-role-list"><?php foreach($roles as $r)echo project_workspace_role_badge($r);?></div><?php $primary=$roles[0];$def=project_role_definition((string)$primary['role']);?><ul class="pw-responsibility-list"><?php foreach((array)($def['responsibilities']??[]) as $responsibility):?><li><?=e((string)$responsibility)?></li><?php endforeach;?></ul><?php else:?><p><?=e(tr('Vyber si oblast, za kterou budeš primárně odpovídat. Systém ti doporučí role podle mastery i toho, co sis ještě nevyzkoušel/a.'))?></p><?php endif;?></section>
      </div>
      <section class="pw-stat-row"><article><span><?=e(tr('Moje úkoly'))?></span><strong><?= (int)$summary['tasks_done'] ?> / <?= (int)$summary['tasks_total'] ?></strong><small><?=e(tr('dokončeno'))?></small></article><article><span><?=e(tr('Tým'))?></span><strong><?=count((array)$group['member_keys'])?></strong><small><?=e(tr('členové'))?></small></article><article><span>QA</span><strong><?= (int)$health['qa_open'] ?></strong><small><?=e(tr('otevřené nálezy'))?></small></article><article><span><?=e(tr('Team pulse'))?></span><strong><?= (int)$pulse['counts']['green'] ?> / <?= (int)$pulse['responses'] ?></strong><small><?=e(tr('jde dobře'))?></small></article></section>
      <div class="pw-overview-lower">
        <section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Co potřebuje pozornost'))?></div><h2><?=e(tr('Konkrétní signály'))?></h2><p><?=e(tr('Žádné magické „team score“. Jen věci, podle kterých se dá jednat.'))?></p></div></div><div class="pw-signals"><?php foreach((array)$health['signals'] as $signal):?><article class="severity-<?=e((string)$signal['severity'])?>"><i><?=($signal['severity']==='ok'?'✓':'!')?></i><span><?=e((string)$signal['text'])?></span></article><?php endforeach;?></div></section>
        <section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Tým'))?></div><h2><?=e(tr('Kdo za co ručí'))?></h2></div><a class="text-link" href="<?=e(project_workspace_url($projectId,'team'))?>"><?=e(tr('Detail →'))?></a></div><div class="pw-team-compact"><?php foreach((array)$group['member_keys'] as $mk):if(!isset($students[$mk]))continue;$mrs=project_roles_for_student($groupId,(string)$mk);?><article><div class="social-avatar"><?=e(u_substr((string)$students[$mk]['label'],0,1))?></div><div><strong><?=e((string)$students[$mk]['label'])?><?=$mk===$me?e(tr(' · ty')):''?></strong><span><?= $mrs?e(implode(' + ',array_map(static fn($r)=>project_role_label((string)$r['role']),$mrs))):e(tr('role čeká na výběr')) ?></span></div></article><?php endforeach;?></div></section>
      </div>
      <?php $previousGrowth=project_previous_growth_note($classId,$me,$projectId);if($previousGrowth):?><section class="dashboard-panel pw-carry-over"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Z minulého projektu'))?></div><h2><?=e(tr('Jedna věc, kterou sis chtěl/a přenést dál'))?></h2></div></div><blockquote><?=e((string)$previousGrowth['next_time'])?></blockquote><p><?=e(tr('Retrospektiva má smysl jen tehdy, když ovlivní další práci. Až bude relevantní, zkus tento závěr vědomě použít.'))?></p></section><?php endif;?>
      <?php $skillReqs=skill_project_requirements($classId,$projectId);if($skillReqs):?><section class="dashboard-panel pw-skill-context"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Proč to děláme?'))?></div><h2><?=e(tr('Projekt rozvíjí tyto ověřitelné skills'))?></h2><p><?=e(tr('Projektová role a finální teacher evaluation mohou vytvořit Mastery Evidence. Samotné klikání nebo počet tasků mastery nezvyšuje.'))?></p></div></div><div class="pw-skill-context-grid"><?php foreach($skillReqs as $r):$s=$r['skill'];$p=skill_progress($classId,(string)$s['slug']);?><a href="<?=e(module_url('skill_detail',['skill'=>(string)$s['slug']]))?>"><strong><?=e((string)$s['name'])?></strong><span><?=edu_number((float)($p['mastery_percent']??0),0)?> % mastery</span><small><?=e(tr('doporučeno {percent} %',['percent'=>edu_number((float)$r['recommended_mastery'],0)]))?></small></a><?php endforeach;?></div></section><?php endif;?>

