        <section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Moje práce'))?></div><h2><?=e(tr('Co mám udělat teď?'))?></h2><p><?=e(tr('Nejdřív vlastní odpovědnosti. Celý týmový board je níže.'))?></p></div><button class="btn primary" type="button" data-open-task-form><?=e(tr('+ Úkol'))?></button></div><div class="pw-my-task-list"><?php if(!$myTasks):?><div class="pw-empty-mini"><?=e(tr('Zatím nemáš přiřazený úkol. Domluvte si v týmu první konkrétní odpovědnosti.'))?></div><?php endif;?><?php foreach($myTasks as $t):?><a class="pw-task-row status-<?=e((string)$t['status'])?>" href="<?=e(project_workspace_url($projectId,'work',['task'=>(string)$t['id']]))?>"><i></i><div><strong><?=e((string)$t['title'])?></strong><span><?=e(project_workspace_task_status_label((string)$t['status']))?><?php if($t['role']):?> · <?=e(project_role_label((string)$t['role']))?><?php endif;?></span></div><?php if($t['due_at']):?><time><?=e(date('d.m.',strtotime((string)$t['due_at'])))?></time><?php endif;?></a><?php endforeach;?></div></section>
        <section class="dashboard-panel pw-board"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Týmový board'))?></div><h2><?=e(tr('Společná práce bez Jira chaosu'))?></h2><p><?=e(tr('K udělání → Pracuji → Review → QA → Hotovo. Blokované úkoly jsou viditelné zvlášť.'))?></p></div></div><div class="pw-board-grid"><?php foreach(['todo','in_progress','review','qa','done'] as $status):?><div class="pw-board-col"><header><strong><?=e(project_workspace_task_status_label($status))?></strong><span><?=count(array_filter($tasks,static fn($t)=>(string)($t['status']??'')===$status))?></span></header><?php foreach($tasks as $t):if((string)$t['status']!==$status)continue;?><a class="pw-board-card" href="<?=e(project_workspace_url($projectId,'work',['task'=>(string)$t['id']]))?>"><strong><?=e((string)$t['title'])?></strong><span><?=e((string)($students[(string)$t['owner_key']]['label']??tr('Bez vlastníka')))?></span><?php if($t['role']):?><small><?=e(project_role_label((string)$t['role']))?></small><?php endif;?></a><?php endforeach;?></div><?php endforeach;?></div><?php $blocked=array_values(array_filter($tasks,static fn($t)=>(string)$t['status']==='blocked'));if($blocked):?><div class="pw-blocked-lane"><strong><?=e(tr('⚠ Blokováno'))?></strong><?php foreach($blocked as $t):?><a href="<?=e(project_workspace_url($projectId,'work',['task'=>(string)$t['id']]))?>"><span><?=e((string)$t['title'])?></span><small><?=e((string)$t['blocked_reason'])?></small></a><?php endforeach;?></div><?php endif;?></section>
