ng)($selectedTask['due_at']??''))?>"></label><label><?=e(tr('Komplexita'))?><select name="complexity"><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?=((int)$selectedTask['complexity']===$i?'selected':'')?>><?=e(tr('{n} / 5',['n'=>$i]))?></option><?php endfor;?></select></label></div><label><?=e(tr('Hotovo znamená'))?><textarea name="definition_of_done" rows="4"><?=e(implode("
