atings'][$role]??0)===$i?'selected':'')?>><?=e(tr('{n} / 5',['n'=>$i]))?></option><?php endfor;?></select></label><?php endforeach;?></fieldset><?php endif;?><button class="btn primary" type="submit"><?=e(tr('Uložit sebereflexi'))?></button></form></section>
        <section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow">2 · Peer feedback</div><h2><?=e(tr('Konkrétně k práci, ne k osobnosti'))?></h2><p><?=e(tr('U krajních hodnocení uveď příklad. Peer feedback sám o sobě nikdy automaticky neurčuje známku.'))?></p></div></div><div class="pw-peer-list"><?php foreach((array)$group['member_keys'] as $mk):if($mk===$me||!isset($students[$mk]))continue;$pf=$given[(string)$mk]??null;?><details <?=$pf?'':'open'?>> <summary><span class="social-avatar"><?=e(u_substr((string)$students[$mk]['label'],0,1))?></span><strong><?=e((string)$students[$mk]['label'])?></strong><b><?=e($pf?tr('✓ odevzdáno'):tr('vyplnit'))?></b></summary><form method="post" class="pw-peer-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_peer_feedback"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><input type="hidden" name="reviewee_key" value="<?=e((string)$mk)?>"><?php $crit=['reliability'=>tr('Spolehlivost'),'communication'=>tr('Komunikace'),'collaboration'=>tr('Spolupráce'),'contribution'=>tr('Přínos')];foreach($crit as $key=>$label):?><label><span><?=e($label)?></span><select name="<?=e($key)?>"><option value="0"><?=e(tr('Nedokážu posoudit'))?></option><option value="1" <?=((int)($pf['ratings'][$key]??0)===1?'selected':'')?>><?=e(tr('Zřídka'))?></option><option value="2" <?=((int)($pf['ratings'][$key]??0)===2?'selected':'')?>><?=e(tr('Občas'))?></option><option value="3" <?=((int)($pf['ratings'][$key]??0)===3?'selected':'')?>><?=e(tr('Většinou'))?></option><option value="4" <?=((int)($pf['ratings'][$key]??0)===4?'selected':'')?>><?=e(tr('Spolehlivě'))?></option><option value="5" <?=((int)($pf['ratings'][$key]??0)===5?'selected':'')?>><?=e(tr('Výjimečně'))?></option></select></label><?php endforeach;?><label><?=e(tr('Co udělal/a dobře?'))?><textarea name="praise" rows="2" maxlength="800"><?=e((string)($pf['praise']??''))?></textarea></label><label><?=e(tr('Co by mu/jí příště mohlo pomoct?'))?><textarea name="improve" rows="2" maxlength="800"><?=e((string)($pf['improve']??''))?></textarea></label><div class="pw-feedback-tip"><?=e(tr('Dobrá zpětná vazba:'))?> <b><?=e(tr('situace → chování → dopad'))?></b>.</div><button class="btn secondary" type="submit"><?=e(tr('Uložit feedback'))?></button></form></details><?php endforeach;?></div></section>
        <section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow">3 · <?=e(tr('Tým'))?></div><h2>Keep · Improve · Try</h2><p><?=e(tr('Jeden až dva konkrétní závěry jsou hodnotnější než deset obecných vět.'))?></p></div></div><form method="post" class="pw-team-retro-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_team_retro"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><label><span>KEEP</span><?=e(tr('Co chceme zopakovat?'))?><textarea name="keep" rows="2" maxlength="600"><?=e((string)($myTeamRetro['keep']??''))?></textarea></label><label><span>IMPROVE</span><?=e(tr('Co chceme zlepšit?'))?><textarea name="improve" rows="2" maxlength="600"><?=e((string)($myTeamRetro['improve']??''))?></textarea></label><label><span>TRY NEXT</span><?=e(tr('Co konkrétně zkusíme příště?'))?><textarea name="try_next" rows="2" maxlength="600"><?=e((string)($myTeamRetro['try_next']??''))?></textarea></label><button class="btn secondary" type="submit"><?=e(tr('Uložit týmovou reflexi'))?></button></form><?php if(count($teamRetroRows)>=2):?><div class="pw-team-retro-summary"><strong><?=e(tr('Anonymizovaný souhrn týmu'))?></strong><?php foreach(['keep'=>'KEEP','improve'=>'IMPROVE','try_next'=>'TRY NEXT'] as $key=>$label):?><div><span><?=e($label)?></span><?php foreach($teamRetroRows as $r):if(trim((string)($r[$key]??''))==='')continue;?><p><?=e((string)$r[$key])?></p><?php endforeach;?></div><?php endforeach;?></div><?php endif;?></section>
      </main><aside><section class="dashboard-panel pw-evaluation"><div class="eyebrow">Teacher evaluation</div><?php if($publishedEvals):?><h2><?=e(count($publishedEvals)===1?tr('Ověřená role'):tr('Ověřené role'))?></h2><div class="pw-role-eval-student-list"><?php foreach($publishedEvals as $roleEval):?><article><div><strong><?=e(project_role_label((string)$roleEval['role']))?></strong><span><?=e($roleEval['score']>=85?'Strong+':($roleEval['score']>=70?'Competent':'Developing'))?></span></div><b><?=edu_number((float)$roleEval['score'],0)?> %</b><?php if($roleEval['strengths']):?><p><strong><?=e(tr('Silná stránka:'))?></strong> <?=e((string)$roleEval['strengths'])?></p><?php endif;?><?php if($roleEval['next_focus']):?><p><strong><?=e(tr('Další fokus:'))?></strong> <?=e((string)$roleEval['next_focus'])?></p><?php endif;?></article><?php endforeach;?></div><p class="pw-eval-note"><?=e(tr('Publikované hodnocení může vytvořit ověřenou Project Evidence pro relevantní Skill Tree.'))?></p><form method="post" class="pw-portfolio-toggle"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="project_portfolio_toggle"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="group_id" value="<?=e($groupId)?>"><button class="btn secondary wide" type="submit"><?=e(project_portfolio_is_featured($groupId,$me)?tr('★ Odebrat z Featured projektů'):tr('☆ Přidat do Featured projektů'))?></button><small><?=e(tr('Na profilu můžeš vystavit maximálně 3 ověřené projekty.'))?></small></form><?php else:?><h2><?=e(tr('Čeká na učitele'))?></h2><p><?=e(tr('Učitel při závěrečném hodnocení uvidí tvoje odpovědnosti, výstupy, QA, reflexi i peer feedback jako evidence. Nic z toho samo automaticky nevytvoří známku.'))?></p><?php endif;?></section><?php $peerOwn=project_peer_summary($groupId,$me);if($peerOwn['count']):?><section class="dashboard-panel"><div class="eyebrow"><?=e(tr('Feedback pro tebe'))?></div><h2><?=e(tr('{count} peer review',['count'=>(int)$peerOwn['count']]))?></h2><?php if($peerOwn['anonymous']):?><div class="pw-peer-avg"><?php foreach($peerOwn['ratings'] as $key=>$value):if($value===null)continue;?><span><b><?=edu_number((float)$value,1)?> / 5</b><?=e(['reliability'=>tr('Spolehlivost'),'communication'=>tr('Komunikace'),'collaboration'=>tr('Spolupráce'),'contribution'=>tr('Přínos')][$key]??$key)?></span><?php endforeach;?></div><?php foreach(array_slice((array)$peerOwn['praise'],0,3) as $txt):?><blockquote><?=e((string)$txt)?></blockquote><?php endforeach;?><?php else:?><p><?=e(tr('V malém týmu by anonymita nebyla skutečná. Detail feedbacku proto zůstává učiteli a studentovi se zobrazí až jako učitelem zprostředkovaný závěr.'))?></p><?php endif;?></section><?php endif;?></aside></div>
      <?php endif;?>
    <?php endif;?>
    <script>
    (()=>{const d=document.querySelector('[data-task-dialog]');document.querySelector('[data-open-task-form]')?.addEventListener('click',()=>d?.showModal());document.querySelector('[data-close-task-form]')?.addEventListener('click',()=>d?.close());const status=document.querySelector('[data-task-status]');const wrap=document.querySelector('.pw-block-fields');const sync=()=>{if(wrap)wrap.hidden=status?.value!=='blocked'};status?.addEventListener('change',sync);sync();})();
    </script>
    <?php render_footer();
}

function render_profile_role_experience(string $classId,string $studentKey,bool $isMe): void
{
    $stats=project_role_history_stats($classId,$studentKey);if((int)$stats['evaluations']===0)return;$defs=project_role_definitions();$portfolio=project_portfolio_entries($classId,$studentKey,!$isMe);if($isMe)$portfolio=array_slice($portfolio,0,6);?>
    <section class="dashboard-panel profile-role-experience"><div class="dashboard-panel-head"><div><div class="eyebrow">Team Experience</div><h2><?=e(tr('Ověřené projektové role'))?></h2><p><?=e(tr('Zobrazuje publikovanou zkušenost z projektů, ne počet kliknutí nebo popularitu.'))?></p></div><?php if($isMe):?><a class="text-link" href="?view=project_workspace"><?=e(tr('Project Workspace →'))?></a><?php endif;?></div><div class="profile-role-grid"><?php foreach($defs as $slug=>$def):$count=(int)($stats['role_counts'][$slug]??0);if($count<1)continue;$best=(float)($stats['best_scores'][$slug]??0);?><article><i><?=e((string)$def['icon'])?></i><div><strong><?=e((string)$def['name'])?></strong><span><?=e($count===1?tr('{count} projekt',['count'=>$count]):tr('{count} projekty',['count'=>$count]))?></span></div><b><?=e($best>=85?'Strong':($best>=70?'Competent':'Developing'))?></b></article><?php endforeach;?></div><?php if((int)$stats['distinct_roles']<6):?><div class="profile-role-growth"><span>Growth opportunity</span><p><?=e(tr('Vyzkoušeno {count} / 6 rolí. Další projekt může být příležitost zkusit jiný typ odpovědnosti.',['count'=>(int)$stats['distinct_roles']]))?></p></div><?php endif;?></section>
    <?php if($portfolio):?><section class="dashboard-panel profile-project-portfolio"><div class="dashboard-panel-head"><div><div class="eyebrow">Project Portfolio</div><h2><?=e($isMe?tr('Tvoje ověřené projekty'):tr('Featured projekty'))?></h2><p><?=e($isMe?tr('Projekt se do portfolia dostane až po publikovaném hodnocení role. Tři z nich můžeš označit jako Featured.'):tr('Student zde sdílí pouze ověřenou roli, příspěvky a skills — ne známky ani detailní hodnocení.'))?></p></div></div><div class="profile-project-grid"><?php foreach($portfolio as $entry):?><article class="<?=$entry['featured']?'featured':''?>"><header><div><span><?=e((string)$entry['group_name'])?></span><h3><?=e((string)$entry['project_title'])?></h3></div><?php if($entry['featured']):?><b><?=e(tr('★ Featured'))?></b><?php endif;?></header><div class="profile-project-roles"><?php foreach((array)$entry['roles'] as $role):?><span><?=e(project_role_label((string)$role))?></span><?php endforeach;?></div><?php if($entry['contributions']):?><div class="profile-project-contrib"><strong><?=e(tr('Ověřené příspěvky'))?></strong><?php foreach((array)$entry['contributions'] as $c):?><span>✓ <?=e((string)$c)?></span><?php endforeach;?></div><?php endif;?><?php if($entry['skills']):?><div class="profile-project-skills"><strong>Skills</strong><?php foreach(array_slice((array)$entry['skills'],0,6) as $slug):$sk=skill_find((string)$slug);?><span><?=e((string)($sk['name']??$slug))?></span><?php endforeach;?></div><?php endif;?><?php if($isMe):?><footer><span>Teacher-verified role evidence</span><b><?=edu_number((float)$entry['average_score'],0)?> %</b></footer><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
    <?php
}

